import json,pathlib
p=pathlib.Path(__file__).parent
data=json.loads((p/'positions.json').read_text())
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>262-Move Tablebase — 60-Second Animation</title>
<style>
:root{color-scheme:dark;font-family:system-ui,-apple-system,Segoe UI,sans-serif}*{box-sizing:border-box}body{margin:0;background:#0e1725;color:#eef3f9;min-height:100vh;display:flex;justify-content:center;align-items:center;padding:18px}.app{width:min(980px,100%)}h1{font-size:clamp(1.25rem,3vw,2rem);margin:0 0 8px}p{color:#b9c8d8;line-height:1.5;margin:5px 0 15px}.layout{display:grid;grid-template-columns:minmax(300px,560px) minmax(240px,1fr);gap:24px;align-items:start}.board{width:100%;aspect-ratio:1;display:grid;grid-template-columns:repeat(8,minmax(0,1fr));grid-template-rows:repeat(8,minmax(0,1fr));border:5px solid #64748b;border-radius:6px;overflow:hidden}.square{display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;aspect-ratio:1;font-family:'DejaVu Sans','Arial Unicode MS',serif;font-size:clamp(24px,5.6vw,54px);line-height:1;position:relative}.light{background:#ebd8b6}.dark{background:#a57d55}.square.from{box-shadow:inset 0 0 0 5px #e9c46a}.square.to{background:#f4ca54}.piece{filter:drop-shadow(1px 2px 1px #0009)}.whitepiece{color:#fff;text-shadow:-1px -1px 2px #222,1px 1px 2px #222,0 0 2px #222}.blackpiece{color:#151d28;text-shadow:0 0 1px white}.panel{background:#172438;border:1px solid #33465e;border-radius:12px;padding:18px}.stat{font-size:2rem;font-weight:750;font-variant-numeric:tabular-nums}.small{font-size:.87rem;color:#bacadd}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}button{background:#315e92;color:white;border:1px solid #6389b3;border-radius:7px;padding:10px 14px;font-weight:650;cursor:pointer}button:hover{background:#4275ac}button:disabled{opacity:.45;cursor:default}input[type=range]{width:100%;accent-color:#dfbb6d}.tag{display:inline-block;padding:5px 9px;background:#2e4663;border-radius:20px;font-size:.82rem;margin:7px 0}.source{font-size:.8rem;color:#bacadd;margin-top:14px}.source a{color:#9dd0ff}.finish{color:#f3d58a;font-weight:750}@media(max-width:720px){.layout{grid-template-columns:1fr}.board{max-width:540px;margin:auto}.panel{max-width:540px;margin:auto;width:100%}}
</style></head><body><main class="app"><h1>262 Moves to Mate — A Tablebase Discovery</h1><p>Six pieces. No pawns. A verified published sequence of 523 half-moves, compressed into <strong>60 seconds</strong> with accelerating playback.</p><div class="layout"><div id="board" class="board" aria-label="Chessboard"></div><aside class="panel"><div class="tag">K + R + N vs K + N + N</div><div class="small">Move</div><div class="stat" id="moveNumber">0 / 262</div><div class="small" id="notation">Initial position</div><div class="buttons"><button id="play">▶ Play</button><button id="restart">↺ Restart</button><button id="end">End position</button></div><label class="small" for="scrub">Scrub through the game</label><input id="scrub" type="range" min="0" max="523" value="0"><p id="status">Ready · playback accelerates toward mate.</p><p class="small">The original tablebase line was published by ChessBase, annotated by Helmut Conrady. The published line ends with <strong>262.Rh2#</strong>. The line disregards the fifty-move draw rule.</p><p class="source">Source: <a href="https://en.chessbase.com/post/just-one-of-17-823-400-766-positions-2" target="_blank" rel="noopener">ChessBase, “Just one of 17,823,400,766 positions” (2015)</a> · Based on Conrady's 2002 analysis.</p></aside></div></main>
<script>
const DATA=__FRAMES__;
const frames=DATA.frames;
const board=document.getElementById('board'),play=document.getElementById('play'),scrub=document.getElementById('scrub'),status=document.getElementById('status');
const glyph={K:'♔',Q:'♕',R:'♖',B:'♗',N:'♘',P:'♙',k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'};
let current=0,playing=false,startAt=0,elapsedBefore=0,raf=0;
const DURATION=60000, N=frames.length-1;
// First 20 full moves (40 plies): one second per full move.
// Then each half-move interval decreases linearly to the final checkmate.
// The sum of all intervals is exactly 60 seconds.
const INTRO_PLIES=40, INTRO_PLY_MS=500, REMAINING=N-INTRO_PLIES;
const FASTEST_PLY_MS=20;
const FIRST_ACCEL_PLY_MS=2*(DURATION-INTRO_PLIES*INTRO_PLY_MS)/REMAINING-FASTEST_PLY_MS;
const times=[0];
for(let i=1;i<=N;i++){
  const interval=i<=INTRO_PLIES ? INTRO_PLY_MS :
    FIRST_ACCEL_PLY_MS+(FASTEST_PLY_MS-FIRST_ACCEL_PLY_MS)*(i-INTRO_PLIES-1)/(REMAINING-1);
  times.push(times[i-1]+interval);
}
function timeAt(i){return times[i]}
function frameAt(ms){let lo=0,hi=N;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(timeAt(mid)<=ms)lo=mid;else hi=mid-1}return lo}
function pieces(fen){let out=[],rows=fen.split(' ')[0].split('/');for(let y=0;y<8;y++){let x=0;for(const c of rows[y]){if(/\d/.test(c)){x+=Number(c)}else{out[y*8+x]=c;x++}}}return out}
function render(i){current=i;scrub.value=String(i);const f=frames[i],p=pieces(f.fen);let from='',to='';if(f.uci){from=f.uci.slice(0,2);to=f.uci.slice(2,4)}const sqs=[];for(let y=0;y<8;y++)for(let x=0;x<8;x++){const n=y*8+x,c=p[n],square='abcdefgh'[x]+(8-y);const classes=['square',(x+y)%2?'dark':'light'];if(square===from)classes.push('from');if(square===to)classes.push('to');const pc=c?`<span class="piece ${c===c.toUpperCase()?'whitepiece':'blackpiece'}">${glyph[c]}</span>`:'';sqs.push(`<div class="${classes.join(' ')}">${pc}</div>`)}board.innerHTML=sqs.join('');document.getElementById('moveNumber').textContent=`${Math.ceil(i/2)} / 262`;document.getElementById('notation').textContent=i?`${i%2?'White':'Black'}: ${f.san} · ply ${i} / 523`:'Initial position';if(i===N){status.innerHTML='<span class="finish">Checkmate — 262.Rh2#</span>';play.textContent='▶ Replay'}else if(!playing){status.textContent='Paused · ready to play';play.textContent='▶ Play'}}
function pause(){if(playing){elapsedBefore=Math.min(DURATION,performance.now()-startAt);playing=false;cancelAnimationFrame(raf);play.textContent='▶ Play';status.textContent='Paused'}}
function tick(now){if(!playing)return;const elapsed=Math.min(DURATION,now-startAt);const index=frameAt(elapsed);if(index!==current)render(index);if(elapsed>=DURATION){playing=false;render(N);return}raf=requestAnimationFrame(tick)}
function begin(){if(playing){pause();return}if(current===N){current=0;elapsedBefore=0;render(0)}startAt=performance.now()-elapsedBefore;playing=true;play.textContent='Ⅱ Pause';status.textContent='Playing · accelerating to checkmate';raf=requestAnimationFrame(tick)}
play.onclick=begin;document.getElementById('restart').onclick=()=>{pause();elapsedBefore=0;render(0)};document.getElementById('end').onclick=()=>{pause();elapsedBefore=DURATION;render(N)};scrub.oninput=()=>{pause();const i=Number(scrub.value);elapsedBefore=timeAt(i);render(i)};render(0);
</script></body></html>'''
html=html.replace('__FRAMES__',json.dumps(data,separators=(',',':')))
(p/'long_endgame_262.html').write_text(html)
(p/'README.md').write_text('''# 262-move pawnless tablebase animation\n\nOpen `long_endgame_262.html` in any modern browser. Works offline. Click Play for an accelerating 60-second replay, or use Pause, Restart, End, and the move slider.\n\n**Source:** Frederic Friedel / ChessBase, *Just one of 17,823,400,766 positions* (2015 republication), with the complete 262-move line annotated by Helmut Conrady (2002). https://en.chessbase.com/post/just-one-of-17-823-400-766-positions-2\n\n**Position:** `6N1/5KR1/2n5/8/8/8/2n5/1k6 w - - 0 1`.\n\n**Material:** White K+R+N vs Black K+N+N; no pawns. **Length:** 523 plies (White's 262nd move checkmates).\n\n**Important:** This is a historical tablebase-derived line, not a solution computed by our KRK solver. It exceeds the fifty-move rule and is a theoretical mate line under rules ignoring that draw restriction.\n\n`source_moves.txt` holds the transcribed SAN mainline. `build.py` converts it into `positions.json` while independently checking legal piece movement, capture notation, and king safety. `make_html.py` creates the standalone HTML. No libraries are required to run the animation.\n''')
print('Wrote',p/'long_endgame_262.html',len(html),'bytes')
